head.b:skin:
/* <Variable name="page.background" description="Page background" type="color" default="#f3f0e6" value="#f3f0e6"/><Variable name="page.text" description="Text color" type="color" default="#353c30" value="#353c30"/><Variable name="theme.accent" description="Accent color" type="color" default="#64704f" value="#64704f"/> */
/* Blogger stylesheet compatibility: restore the spacing Blogger's own widget stylesheet removes, and keep post content inside a phone screen. */
h1{margin:.67em 0}h2{margin:.83em 0}h3{margin:1em 0}h4{margin:1.33em 0}h1,h2,h3,h4,a img{position:static}body{padding:0;word-break:normal}.post-body{width:auto;overflow-x:auto}.post-body a[style*='margin-left'],.post-body a[style*='margin-right']{margin-inline:0!important}.post-body .separator,.post-body .tr-caption-container{max-width:100%}.widget .post-body ul,.widget .post-body ol{margin:1em 0;padding:0 0 0 1.4em;line-height:inherit}.widget .post-body li{margin:0 0 .35em;padding:0}.latest-empty{display:none}.single-view{font-size:1rem}.single-view .post-title{overflow-wrap:anywhere}
:root{--bg:$(page.background);--ink:$(page.text);--accent:$(theme.accent);--heading:"DM Serif Display",Georgia,serif;--body:"Manrope",sans-serif}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 var(--body)}h1,h2,h3{font-family:var(--heading);line-height:1.15}a{color:inherit;text-underline-offset:4px}a:hover{text-decoration-thickness:2px}img{max-width:100%;height:auto}svg{max-width:100%;height:auto}button,input{font:inherit}a:focus-visible,button:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid currentColor;outline-offset:5px}a,button,summary{touch-action:manipulation}nav{max-width:100%}p,h1,h2,h3,a{overflow-wrap:anywhere}.skip-link{position:fixed;top:-100px;left:16px;z-index:100;background:var(--ink);color:var(--bg);padding:12px}.skip-link:focus{top:12px}.section,.widget{min-width:0;margin:0;padding:0;line-height:inherit}.latest{max-width:1200px;margin:64px auto;padding:0 24px}.posts-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}.post-card{min-width:0}.post-title a{text-decoration:none}.post-title a:hover{text-decoration:underline}.post-media{display:block;aspect-ratio:16/10;overflow:hidden;background:color-mix(in srgb,var(--accent) 12%,var(--bg))}.post-media img{width:100%;height:100%;object-fit:cover}.post-art{height:100%;display:grid;place-items:center;font:italic 70px var(--heading);color:var(--accent)}.post-meta{margin-top:18px;font-size:12px}.post-meta a{margin-right:12px}.pager{display:flex;justify-content:space-between;gap:20px;margin-top:40px;padding-top:20px;border-top:1px solid currentColor}.pager a{padding:10px 0}.post-body{max-width:70ch;margin-inline:auto;overflow-wrap:anywhere}.post-body img,.post-body iframe{max-width:100%}.post-body pre,.post-body table{display:block;overflow:auto;max-width:100%}.single-view .latest{max-width:900px}.single-view .section-heading{display:none}.single-view .post-title{font-size:clamp(32px,5vw,62px)}.single-view #comments{margin-top:60px}.empty-state,.error-state{padding:45px 0}.error-state{max-width:900px;margin:auto;padding:70px 24px}.listing-heading{font-size:clamp(28px,5vw,52px)}#Attribution1,.widget.Attribution{display:none!important}@media(max-width:700px){.posts-grid{grid-template-columns:1fr}.latest{margin:45px auto}.pager{flex-wrap:wrap}}
html{scroll-behavior:smooth}body{margin:0}a{color:inherit}a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid var(--accent);outline-offset:5px}img{max-width:100%}header,footer{position:relative}nav{display:flex;gap:24px;flex-wrap:wrap}nav a{text-decoration:none}.wordmark{text-decoration:none;font-weight:700}.brandline{display:flex;align-items:center;justify-content:space-between;gap:24px}.eyebrow{font-size:12px;letter-spacing:.16em;text-transform:uppercase}.art{display:block;width:100%;height:auto}p{line-height:1.7}.post-title a{text-decoration:none}.post-meta{font-size:11px;letter-spacing:.07em;text-transform:uppercase}.post-excerpt{line-height:1.6}.post-media{display:block;width:100%;aspect-ratio:16/10;object-fit:cover}.section-heading{font-size:30px;margin:0 0 30px}.post-title{font-size:24px;line-height:1.2}.post-card{min-width:0}footer{margin-top:80px}footer p{margin:0}.footerline{display:flex;justify-content:space-between;gap:25px;align-items:center}.page-content,.post-body{max-width:760px;margin:auto}.post-body{line-height:1.8}main>.section-heading,main>.posts-grid{max-width:1200px;margin-left:auto;margin-right:auto}#Attribution1,.widget.Attribution{display:none!important}@media(max-width:700px){.brandline,.footerline{align-items:flex-start;flex-direction:column}nav{gap:16px}.section-heading{font-size:26px}.post-title{font-size:22px}main>.section-heading,main>.posts-grid{margin-left:20px;margin-right:20px}}body{background:#f3f0e6;color:#353c30;font:14px "Manrope",sans-serif}header{padding:30px 6vw}.wordmark{font:30px "DM Serif Display",serif;letter-spacing:-.06em}.wordmark span{font:10px "Manrope",sans-serif;letter-spacing:0;margin-left:20px}nav{font-size:11px}.still-hero{padding:45px 6vw 70px;display:grid;grid-template-columns:.95fr 1fr;gap:10vw;align-items:center}.eyebrow{color:#64704f;font-size:10px}.still-copy h1{font:400 clamp(65px,7.6vw,108px)/.98 "DM Serif Display",serif;letter-spacing:-.04em;margin:28px 0}.still-copy em{color:#64704f}.still-copy p:not(.eyebrow){max-width:320px;color:#5a6254;font-size:14px}.still-button{display:inline-flex;gap:40px;padding:16px 22px;border:1px solid #64704f;border-radius:2px;text-decoration:none;font-size:11px;margin-top:20px;background:#64704f;color:#fff}.still-button span{transition:transform .25s}.still-button:hover span{transform:translate(3px,-3px)}.tiny-note{display:block;margin-top:18px;font-size:10px;color:#6b7063}.still-hero figure{margin:0}.still-hero .art{border-radius:48% 48% 2px 2px}.still-hero figcaption{font-size:9px;letter-spacing:.12em;color:#6b7063;margin-top:15px;text-align:right}.rituals{padding:65px 6vw;background:#e8e7da}.section-intro{text-align:center}.section-intro h2{font:36px "DM Serif Display",serif;font-weight:400;margin:10px 0 40px}.ritual-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:50px}.ritual-grid article{border-top:1px solid #a7ad96;padding-top:25px}.ritual-icon{font:36px Georgia;display:block;margin-bottom:20px}.ritual-grid small{font-size:9px;letter-spacing:.13em}.ritual-grid h3{font:25px "DM Serif Display",serif;margin:15px 0}.ritual-grid p{font-size:12px;color:#5a6254}.ritual-grid a{font-size:11px;text-underline-offset:5px}.journal-heading{margin:65px 6vw 15px}.section-heading{font:400 38px "DM Serif Display",serif;margin:0 6vw 30px}.posts-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:35px;margin:0 6vw}.post-card{background:transparent}.post-media{aspect-ratio:5/4;border-radius:2px;background:#e0decf;filter:saturate(.5)}.post-meta{font-size:9px;color:#64704f;margin-top:22px}.post-title{font:25px/1.2 "DM Serif Display",serif;margin:13px 0}.post-excerpt{font-size:12px;color:#5a6254}.still-philosophy{margin:80px 6vw 0;padding:55px 0;border-top:1px solid #bac0aa;display:grid;grid-template-columns:1fr 1.1fr;gap:80px;align-items:center}.still-philosophy h2{font:55px/1.03 "DM Serif Display",serif;margin:20px 0}.still-philosophy p:not(.eyebrow){max-width:440px;color:#5a6254;font-size:13px}.still-philosophy a{font-size:11px;text-underline-offset:5px}.stone-mark{display:flex;flex-direction:column;align-items:center;gap:7px}.stone-mark span{display:block;background:#b1b59e;border-radius:50% 45% 40% 45%;height:65px;width:170px}.stone-mark span:nth-child(2){width:230px;background:#969d83}.stone-mark span:nth-child(3){width:300px;background:#7d866a}footer{background:#dde0d0;padding:40px 6vw;margin-top:25px;font-size:10px}.still-footer{font:36px "DM Serif Display",serif}footer a{text-underline-offset:5px}@media(max-width:700px){.wordmark span{display:none}.still-hero{grid-template-columns:1fr;gap:40px;padding-top:30px}.still-copy h1{font-size:76px}.still-hero figure{max-width:450px}.ritual-grid,.posts-grid,.still-philosophy{grid-template-columns:1fr}.ritual-grid{gap:30px}.still-philosophy{gap:40px}.stone-mark{padding:20px 0}.still-philosophy h2{font-size:45px}.post-media{aspect-ratio:16/10}.section-intro h2{font-size:30px}}
.latest{max-width:none;margin:55px 0;padding:0}.latest>.section-heading,.latest>.posts-grid{max-width:none}a:hover span,a:focus-visible span{transition:transform .2s}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*::before,*::after{animation:none!important;transition:none!important}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto!important}*,*::before,*::after{animation:none!important;transition:none!important}.post-media img{transform:none!important}}@media print{nav,.skip-link,.pager{display:none!important}body{background:white;color:black}}
